with latest as (select * from (select *, rank() over (partition by carrier order by shipped_date desc nulls first) as rn from shipments) ranked where rn = 1) select date_trunc('year', delivered_date) as year_start, case when cost >= 105 then 'LARGE' else 'SMALL' end as cost_tier, percentile_approx(cost, array(0.25, 0.5, 0.75)) as cost_quartiles, count(*) as row_count, count_if(status = 'RETURNED') as returned_events, min(cost) as min_cost, dense_rank() over (partition by date_trunc('year', delivered_date) order by count_if(status = 'RETURNED') desc) as returned_events_dense_rank from latest group by 1, 2 order by row_count desc;
